from taf.selenium.gnb.oam.coam.classical.pages import v20b, v21a, v21b
from taf.selenium.gnb.oam.coam.classical.pages.login_management import CoamLoginPage, LogoutPage
from taf.selenium.gnb.oam.coam.classical.pages.login_management import LabAccessLoginPage
from taf.selenium.gnb.oam.coam.classical.pages.account_management import UserAccountManagementForNemuadmin
from taf.selenium.gnb.oam.coam.classical.common.debug import Debug
from taf.selenium.gnb.oam.coam.classical.pages.bts_status import BtsStatus
from taf.selenium.gnb.oam.coam.classical.pages.bts_basic_info import BtsBasicInfo
from taf.selenium.gnb.oam.coam.classical.pages.configuration import Configuration
from taf.selenium.gnb.oam.coam.classical.pages.alarms import Alarms
from taf.selenium.gnb.oam.coam.classical.pages.diagnostic import Diagnostic
from taf.selenium.gnb.oam.coam.classical.pages.software import Software
from taf.selenium.gnb.oam.coam.classical.pages.performance import Performance
from taf.selenium.gnb.oam.coam.classical.pages.modals import WebElementManagerReloadModal, PlugAndPlayModal
from taf.selenium.gnb.oam.coam.classical.pages.rnd_mode import RndMode
from taf.selenium.gnb.oam.coam.classical.pages.procedures import Procedures
from taf.selenium.gnb.oam.coam.classical.pages.options import Options
from taf.selenium.gnb.oam.coam.classical.pages.modals import BtsStartUpViewModal
from taf.selenium.gnb.oam.coam.classical.pages.browser import Browser


class Coam(object):
    def __init__(self, driver, download_checker, screenshot_dir):
        self._driver = driver
        self._download_checker = download_checker
        self._login_page = None
        self._logout_page = None
        self._lab_access_login = LabAccessLoginPage(self._driver)
        self._debug = Debug(self._driver, screenshot_dir)
        self._user_account_management_for_admin = UserAccountManagementForNemuadmin(self._driver)
        self._bts_basic_info = BtsBasicInfo(self._driver)
        self._bts_status = BtsStatus(self._driver)
        self._bts_start_up_view_modal = BtsStartUpViewModal(self._driver)
        self._configuration = Configuration(self._driver, download_checker)
        self._performance = Performance(self._driver, download_checker)
        self._alarms = Alarms(self._driver, download_checker)
        self._software = Software(self._driver, download_checker)
        self._web_element_manager_reload_modal = WebElementManagerReloadModal(self._driver)
        self._plug_and_play_modal = PlugAndPlayModal(self._driver)
        self._diagnostic = Diagnostic(self._driver, download_checker)
        self._procedures = Procedures(self._driver)
        self._rnd_mode = RndMode(self._driver, download_checker)
        self._options = Options(self._driver)
        self._browser = Browser(self._driver)

    @property
    def download_checker(self):
        return self._download_checker

    @property
    def debug(self):
        return self._debug

    @property
    def lab_access_login(self):
        return self._lab_access_login

    @property
    def login_page(self):
        return self._login_page

    @property
    def logout_page(self):
        return self._logout_page

    @property
    def user_account_management_for_admin(self):
        return self._user_account_management_for_admin

    @property
    def bts_basic_info(self):
        return self._bts_basic_info

    @property
    def bts_status(self):
        return self._bts_status

    @property
    def bts_start_up_view_modal(self):
        return self._bts_start_up_view_modal

    @property
    def configuration(self):
        return self._configuration

    @property
    def performance(self):
        return self._performance

    @property
    def alarms(self):
        return self._alarms

    @property
    def software(self):
        return self._software

    @property
    def web_element_manager_reload_modal(self):
        return self._web_element_manager_reload_modal

    @property
    def plug_and_play_modal(self):
        return self._plug_and_play_modal

    @property
    def diagnostic(self):
        return self._diagnostic

    @property
    def procedures(self):
        return self._procedures

    @property
    def rnd_mode(self):
        return self._rnd_mode

    @property
    def options(self):
        return self._options

    @property
    def browser(self):
        return self._browser

    def login(self, url, username, password, download_checker, screenshot_dir=None,
              wait_session_modal_timeout=10, port=443, ssl=True, timeout=60, modal_action_configurations=None):
        self._download_checker = download_checker
        self._login_page = CoamLoginPage(self._driver, screenshot_dir)
        return self._login_page.login(url=url,
                                      username=username,
                                      password=password,
                                      wait_session_modal_timeout=int(wait_session_modal_timeout),
                                      port=port,
                                      ssl=ssl,
                                      timeout=int(timeout), modal_action_configurations=modal_action_configurations)

    def login_with_offline_mode(self, file_path, download_checker, screenshot_dir=None):
        self._download_checker = download_checker
        self._login_page = CoamLoginPage(self._driver, screenshot_dir)
        self._login_page.login_with_offline_mode(file_path)

    def login_after_screen_lock(self, passwd, timeout):
        self._login_page.login_after_screen_lock(passwd, timeout)

    def logout(self, click_timeout, timeout):
        self._logout_page = LogoutPage(self._driver)
        self._logout_page.logout(click_timeout, timeout)


class Coam20B(Coam):
    def __init__(self, driver, download_checker, screenshot_dir):
        super(Coam20B, self).__init__(driver, download_checker, screenshot_dir)
        self._software = v20b.Software(self._driver, download_checker)
        self._diagnostic = v20b.Diagnostic(driver, self.download_checker)
        self._rnd_mode = v20b.RndMode(driver, self.download_checker)


class Coam21A(Coam20B):
    def __init__(self, driver, download_checker, screenshot_dir):
        super(Coam21A, self).__init__(driver, download_checker, screenshot_dir)
        self._diagnostic = v21a.Diagnostic(driver, self.download_checker)
        self._rnd_mode = v21a.RndMode(driver, self.download_checker)


class Coam21B(Coam21A):
    def __init__(self, driver, download_checker, screenshot_dir):
        super(Coam21B, self).__init__(driver, download_checker, screenshot_dir)
        self._diagnostic = v21b.Diagnostic(driver, self.download_checker)
        self._rnd_mode = v21b.RndMode(driver, self.download_checker)
        self._configuration = v21b.Configuration(driver, self.download_checker)
